	"math/rand"
	"net"
	"os"
	"strings"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

const (
	defaultPFCPPort = 8805
	readTimeout     = 2 * time.Second
